from itertools import permutations
sides=['T','E','X','I']
res=set()
for p in permutations(sides):
    if p[0]!='T': continue
    cyc=list(p)
    nxt={cyc[i]:cyc[(i+1)%4] for i in range(4)}
    if nxt['T']=='E' and nxt['X']=='I':
        res.add(cyc[(cyc.index('X')+2)%4])
opts={'A':'T','B':'O','C':'I','D':'E'}
assert res=={'T'}
v=res.pop()
assert v==opts['A']
for k in 'BCD': assert v!=opts[k]
